import{_ as a,o as t,c as i,a2 as s}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"API Keys Management","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/api-keys.md","filePath":"en/guide/api-keys.md"}'),o={name:"en/guide/api-keys.md"};function r(n,e,l,c,d,h){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="api-keys-management" tabindex="-1">API Keys Management <a class="header-anchor" href="#api-keys-management" aria-label="Permalink to &quot;API Keys Management&quot;">​</a></h1><p>The API key is your identifier for accessing the OpenRussiaRouter API. One key works for all models.</p><h2 id="creating-a-key" tabindex="-1">Creating a Key <a class="header-anchor" href="#creating-a-key" aria-label="Permalink to &quot;Creating a Key&quot;">​</a></h2><ol><li>Go to the dashboard.</li><li>In the &quot;API Keys&quot; section, click create.</li><li>Copy the generated key (format <code>sk-or-&lt;36 random characters&gt;</code>).</li></ol><div class="warning custom-block"><p class="custom-block-title">Save your key</p><p>The full raw key is only shown once upon creation. Only its secure SHA-256 hash is saved in our database. If you lose the key, you will have to revoke it and create a new one.</p></div><h2 id="key-format" tabindex="-1">Key Format <a class="header-anchor" href="#key-format" aria-label="Permalink to &quot;Key Format&quot;">​</a></h2><p>All OpenRussiaRouter keys start with the <code>sk-or-</code> prefix. Use the key in the <code>Authorization</code> header when sending HTTP requests:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer sk-or-xxx</span></span></code></pre></div><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ul><li><strong>Do not commit keys to code.</strong> Use environment variables (<code>.env</code>).</li><li><strong>Promptly revoke keys</strong> if you suspect they have been compromised.</li><li>You can create multiple keys for different projects or development environments.</li></ul>',10)])])}const y=a(o,[["render",r]]);export{u as __pageData,y as default};
